function drawGraffiti(index,seed,color,progress,word='ЖАР',rarity=null){
  const slot=index%12,col=slot%6,row=Math.floor(slot/6),x=9+col*68,y=29+row*44,variant=Math.abs(Math.floor(seed||0))%4,p=Math.max(0,Math.min(1,progress));
  const label=rarity?rarityData[rarity]?.[s.language]:'',accent=['#f1cb63','#f4e3a8','#8bd3d9','#f29e73'][variant],rColor=rarity?rarityData[rarity].color:'#e4c66d';
  ctx.save();ctx.beginPath();ctx.rect(x,y,62,43);ctx.clip();ctx.globalAlpha=.94;
  if(rarity==='epic'||rarity==='rare'){ctx.fillStyle=rColor;ctx.globalAlpha=rarity==='epic'?.34:.24;ctx.fillRect(x,y+1,62,2);ctx.fillRect(x,y+39,62,2);ctx.globalAlpha=.94;}
  const text=String(word||'ЖАР').toLocaleUpperCase(),center=x+31,baseline=y+20;ctx.font=`700 ${text.length>5?9:text.length>4?10:12}px "Pixelify Sans", monospace`;ctx.textAlign='center';ctx.textBaseline='middle';
  while(ctx.measureText(text).width>57&&parseFloat(ctx.font)>7)ctx.font=`700 ${parseFloat(ctx.font)-1}px "Pixelify Sans", monospace`;
  ctx.beginPath();ctx.rect(x,y,62*p,43);ctx.clip();ctx.translate(center,baseline);ctx.rotate((variant-1.5)*.025);
  ctx.lineJoin='miter';ctx.textAlign='center';ctx.textBaseline='middle';ctx.font=ctx.font;
  ctx.lineWidth=5;ctx.strokeStyle='#211928';ctx.strokeText(text,2,3);
  ctx.lineWidth=3;ctx.strokeStyle=variant%2?'#f2c95e':'#f1e4be';ctx.strokeText(text,0,0);
  ctx.fillStyle=color;ctx.fillText(text,0,0);
  ctx.globalAlpha=.7;ctx.fillStyle=accent;ctx.fillRect(-Math.min(20,ctx.measureText(text).width*.34),-3,Math.min(40,ctx.measureText(text).width*.68),2);ctx.globalAlpha=.94;ctx.restore();
  if(p>.42){ctx.fillStyle=accent;const sx=x+(variant%2?7:53),sy=y+7;ctx.fillRect(sx,sy,3,3);ctx.fillRect(sx-2,sy+1,7,1);ctx.fillRect(sx+1,sy-2,1,7);}
  if(p>.72){ctx.fillStyle=color;const dripX=x+(variant%2?14:46);ctx.fillRect(dripX,y+24,3,Math.min(7,Math.round((p-.7)*24)));ctx.fillRect(dripX+5,y+26,2,Math.min(5,Math.round((p-.7)*18)));}
  if(label&&p>=1){ctx.globalAlpha=.96;ctx.font='700 6px "Pixelify Sans", monospace';ctx.textAlign='center';ctx.textBaseline='middle';const badge=label;const bw=Math.min(58,ctx.measureText(badge).width+11);ctx.fillStyle='#211b20';ctx.fillRect(x+(62-bw)/2,y+31,bw,9);ctx.fillStyle=rColor;ctx.fillRect(x+(62-bw)/2,y+31,3,9);ctx.fillStyle='#fff4d8';ctx.fillText(badge,x+31,y+35.5);ctx.globalAlpha=1;}
}

