const fs = require('fs');
const targetUrl = 'file:///home/runner/work/PlayGround/PlayGround/index.html';
const check = async () => {
  const targets = await (await fetch('http://127.0.0.1:9222/json/list')).json();
  const target = targets.find(t => t.type === 'page');
  if (!target) { await new Promise(r => setTimeout(r, 100)); return check(); }
  const ws = new WebSocket(target.webSocketDebuggerUrl);
  await new Promise((resolve, reject) => { ws.onopen = resolve; ws.onerror = reject; });
  let id = 0; const pending = new Map();
  ws.onmessage = event => { const m = JSON.parse(event.data); if (m.id && pending.has(m.id)) { pending.get(m.id)(m); pending.delete(m.id); } };
  const send = (method, params={}) => new Promise(resolve => { const n=++id; pending.set(n,resolve); ws.send(JSON.stringify({id:n,method,params})); });
  const evaluate = async expression => {
    const result = await send('Runtime.evaluate', {expression, awaitPromise:true, returnByValue:true});
    if (result.error) throw Error(JSON.stringify(result.error));
    if (result.result.exceptionDetails) throw Error(result.result.exceptionDetails.text);
    return result.result.result.value;
  };
  await send('Page.enable'); await send('Runtime.enable');
  const now=Date.now();
  const save={coins:35,items:[1,1,1,...Array(13).fill(0)],capacity:16,artists:1,efficiency:1,supply:1,wall:1,spawnAt:now+24000,discovered:[true,false,false,false,false,false],drawings:0,combo:0,lastMerge:0,language:'ru',lastSave:now,jobs:[{level:1,progress:990,duration:1000,seed:27,color:'#e4b54e',word:'ИСКРА',phase:'paint',phaseAt:now,artist:0,wallIndex:0}],murals:[]};
  await send('Page.addScriptToEvaluateOnNewDocument',{source:`localStorage.setItem('graffiti-merge-save', ${JSON.stringify(JSON.stringify(save))}); Math.random=()=>0.01;`});
  await send('Page.navigate',{url:targetUrl});
  await new Promise(r=>setTimeout(r,1600));
  const completion=await evaluate(`JSON.parse(localStorage.getItem('graffiti-merge-save'))`);
  const completedState={count:completion.murals.length,rarity:completion.murals[0]?.rarity,word:completion.murals[0]?.word,wallIndex:completion.murals[0]?.wallIndex,phase:completion.jobs[0]?.phase,toast:document.getElementById('toast').textContent,canvas:[document.getElementById('scene').width,document.getElementById('scene').height]};
  await evaluate(`document.getElementById('language').click()`);
  const language=await evaluate(`({lang:document.documentElement.lang,save:JSON.parse(localStorage.getItem('graffiti-merge-save')).language,toast:document.getElementById('toast').textContent})`);
  await evaluate(`document.getElementById('language').click()`);
  await evaluate(`document.querySelector('.board-cell[data-index="0"]').click(); document.querySelector('.board-cell[data-index="1"]').click()`);
  const merged=await evaluate(`JSON.parse(localStorage.getItem('graffiti-merge-save')).items.slice(0,4)`);
  const drag=await evaluate(`(()=>{const cell=document.querySelector('.board-cell[data-index="2"]'),slot=document.querySelector('.artist-slot');const a=cell.getBoundingClientRect(),b=slot.getBoundingClientRect();const x=a.x+a.width/2,y=a.y+a.height/2,tx=b.x+b.width/2,ty=b.y+b.height/2;cell.dispatchEvent(new PointerEvent('pointerdown',{bubbles:true,cancelable:true,pointerId:8,pointerType:'mouse',clientX:x,clientY:y}));document.elementFromPoint(tx,ty).dispatchEvent(new PointerEvent('pointerup',{bubbles:true,cancelable:true,pointerId:8,pointerType:'mouse',clientX:tx,clientY:ty}));return {slot:!!slot,from:cell.style.opacity}})()`);
  await new Promise(r=>setTimeout(r,80));
  const assignment=await evaluate(`JSON.parse(localStorage.getItem('graffiti-merge-save'))`);
  const dimensions=await evaluate(`({viewport:[innerWidth,innerHeight],document:[document.documentElement.scrollWidth,document.documentElement.scrollHeight],canvasRect:(()=>{const r=document.getElementById('scene').getBoundingClientRect();return [Math.round(r.width),Math.round(r.height)]})(),boardRect:(()=>{const r=document.getElementById('board').getBoundingClientRect();return [Math.round(r.width),Math.round(r.height)]})()})`);
  console.log(JSON.stringify({completedState,language,merged,drag,assignedJob:assignment.jobs[0]&&{phase:assignment.jobs[0].phase,word:assignment.jobs[0].word},remainingItems:assignment.items.slice(0,4),dimensions},null,2));
  ws.close();
};
check().catch(e=>{console.error(e);process.exit(1)});

