    const n = ++id;
    pending.set(n, resolve);
    ws.send(JSON.stringify({ id: n, method, params }));
  });
  const evaluate = async expression => {
    const result = await send('Runtime.evaluate', { expression, awaitPromise: true, returnByValue: true });
    if (result.result.exceptionDetails) throw Error(result.result.exceptionDetails.text);
    return result.result.result.value;
  };
  await send('Page.enable');
  await send('Runtime.enable');
  const base = (artists, jobs, coins = 35) => ({
    coins, items: Array(16).fill(0), capacity: 16, artists, efficiency: 1, supply: 1, wall: 1,
    spawnAt: Date.now() + 24000, discovered: [true, false, false, false, false, false], drawings: 0,
    combo: 0, lastMerge: 0, language: 'en', lastSave: Date.now(), jobs, murals: []
  });
  const job = (phase, progress = 0, duration = 100000, phaseAge = 0, artist = 0) => ({
    level: 1, progress, duration, seed: 27 + artist, color: '#e4b54e', word: 'HEAT',
    phase, phaseAt: Date.now() - phaseAge, artist, wallIndex: artist
  });
  const loadSave = async save => {
    await evaluate(`localStorage.setItem('graffiti-merge-save', ${JSON.stringify(JSON.stringify(save))})`);
    await send('Page.reload');
    await delay(120);
  };
  await send('Emulation.setDeviceMetricsOverride', { width: 1280, height: 800, deviceScaleFactor: 1, mobile: false });

  // Two artists complete nearly together: both rewards and mural entries must be saved.
  await loadSave(base(2, [job('paint', 990, 1000), job('paint', 985, 1000, 0, 1)]));
  await delay(250);
  const afterCompletions = await evaluate(`(()=>{const s=JSON.parse(localStorage.getItem('graffiti-merge-save'));return {coins:s.coins,counter:document.getElementById('coins').textContent,drawings:s.drawings,murals:s.murals.length,rewards:s.murals.map(m=>m.rarity),progress:document.getElementById('progress-percent').textContent,stage:document.getElementById('progress-stage').textContent,phases:s.jobs.map(j=>j&&j.phase)}})()`);
  assert.equal(afterCompletions.coins, 65, 'two artworks should each add 15 coins');
  assert.equal(afterCompletions.counter, '65', 'coin counter should update in the completion frame');
  assert.equal(afterCompletions.drawings, 2);
  assert.equal(afterCompletions.murals, 2);
  assert(afterCompletions.phases.every(phase => phase === 'return'), 'both completed jobs should return');
  await send('Page.reload');
  await delay(120);
  const afterReload = await evaluate(`(()=>{const s=JSON.parse(localStorage.getItem('graffiti-merge-save'));return {coins:s.coins,counter:document.getElementById('coins').textContent,drawings:s.drawings,murals:s.murals.length}})()`);
  assert.deepEqual(afterReload, { coins: 65, counter: '65', drawings: 2, murals: 2 }, 'both rewards must persist after reload');

  // Paint takes precedence over walking/returning, and only a return phase can report 100%.
  await loadSave(base(3, [job('return', 100000, 100000, 0, 0), job('walk', 0, 100000, 0, 1), job('paint', 50000, 100000, 0, 2)]));
  const concurrent = await evaluate(`({percent:document.getElementById('progress-percent').textContent,stage:document.getElementById('progress-stage').textContent})`);
  assert.equal(concurrent.percent, '50%', 'active painting must take precedence over a returning job');
  assert.equal(concurrent.stage, 'COLORING');
  await loadSave(base(2, [job('return', 100000, 100000), job('walk', 0, 100000, 0, 1)]));
  const walking = await evaluate(`({percent:document.getElementById('progress-percent').textContent,stage:document.getElementById('progress-stage').textContent})`);
  assert.equal(walking.percent, '0%', 'walking progress must not show completion');
  assert.equal(walking.stage, 'STARTING');
  await loadSave(base(1, [job('return', 100000, 100000)]));
  const returning = await evaluate(`({percent:document.getElementById('progress-percent').textContent,stage:document.getElementById('progress-stage').textContent})`);
  assert.equal(returning.percent, '100%');
  assert.equal(returning.stage, 'COMPLETED');
  await loadSave(base(1, [job('paint', 50000, 100000)]));
  const progressBefore = Number((await evaluate(`document.getElementById('progress-percent').textContent`)).replace('%', ''));
  await delay(180);
  const progressAfter = Number((await evaluate(`document.getElementById('progress-percent').textContent`)).replace('%', ''));
  assert(progressAfter >= progressBefore, 'progress should continuously advance');
  assert(progressAfter < 100, 'painting must remain below 100% until completed');

  const responsive = [];
  for (const [width, height, mobile] of [[1280, 800, false], [390, 844, true], [844, 390, true]]) {
    await send('Emulation.setDeviceMetricsOverride', { width, height, deviceScaleFactor: 1, mobile });
    await delay(80);
    responsive.push(await evaluate(`(()=>{const r=document.querySelector('.workshop-card').getBoundingClientRect();return {viewport:[innerWidth,innerHeight],workshop:[Math.round(r.width),Math.round(r.height)],share:+(r.height/innerHeight*100).toFixed(1),document:[document.documentElement.scrollWidth,document.documentElement.scrollHeight]}})()`));
  }
  console.log(JSON.stringify({ afterCompletions, afterReload, concurrent, walking, returning, progress: [progressBefore, progressAfter], responsive }, null, 2));
  ws.close();
})().catch(error => { console.error(error); process.exit(1); });

